CREATE TABLE `lsboutique`.`premoderation_items` ( `id` INT NOT NULL AUTO_INCREMENT , `code` INT NOT NULL , `ean` VARCHAR(100) NOT NULL , `sku` VARCHAR(100) NOT NULL , `name` VARCHAR(100) NOT NULL , `size` VARCHAR(50) NOT NULL , `color` VARCHAR(50) NOT NULL , `barcode` VARCHAR(30) NOT NULL , `quantity` INT NOT NULL , `sum` FLOAT NOT NULL , `created_at` DATE NOT NULL , `order_number` INT NOT NULL , `accepted_at` DATETIME NOT NULL , `accepted_user_id` INT NOT NULL , `accepted` TINYINT NOT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;
